#include <optional>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::optional<int> value{4}, empty{std::nullopt};
    std::nullopt_t tag = std::nullopt;
    (void)tag;
    assert(value > empty && value == 4);
    try {
        (void)empty.value();
        assert(false);
    } catch (const std::bad_optional_access &) {
    }
    {
        std::optional<int> scoped{2};
        assert(*scoped == 2);
    }
}
